mapper.update:
update coop_settlement head
set head.amount = (select coalesce(sum(detail.origin_amount), 0)
                   from coop_settlement_detail detail where detail.settlement_id = head.id),
    head.verified_heads = (select count(distinct detail.registration_id)
                           from coop_settlement_detail detail where detail.settlement_id = head.id)
where head.id = #{settlementId}
